/* Reservation preview: no customer data is persisted or sent to a server. */
function rentalDate(offset=0){const d=new Date();d.setDate(d.getDate()+offset);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function validateRentalDates(values,today=rentalDate()){return values.pickupDate>=today&&new Date(values.returnDate+'T'+values.returnTime)-new Date(values.pickupDate+'T'+values.pickupTime)>=86400000;}

function calculateRentalEstimate(vehicle,options,rates,values){
 const duration=new Date(values.returnDate+'T'+values.returnTime)-new Date(values.pickupDate+'T'+values.pickupTime);
 if(!Number.isFinite(duration)||duration<86400000||!vehicle.publishedRate)return null;
 const days=Math.ceil(duration/86400000),weeks=days<6?0:Math.floor((days+1)/7),dailyDays=days%7===6?0:days-weeks*7;
 const vehicleTotal=weeks*vehicle.publishedRate.week+dailyDays*vehicle.publishedRate.day,extras=[],unpriced=[];
 options.forEach((o,i)=>{const quantity=Math.min(o.usesAmount?o.amountMax:1,Math.max(0,Number(values['extra'+i])||0));if(!quantity)return;const rate=rates[o.tsdCode];if(!Number.isFinite(rate)){unpriced.push(o.name);return;}extras.push({name:o.name,code:o.tsdCode,quantity,rate,total:rate*quantity*days});});
 const roadside=days*2,subtotal=vehicleTotal+extras.reduce((sum,e)=>sum+e.total,0)+roadside+15,tax=subtotal*.05,surcharge=(subtotal+tax)*.13;
 return {days,weeks,dailyDays,vehicleTotal,extras,unpriced,roadside,subtotal,tax,surcharge,total:subtotal+tax+surcharge};
}

function initReservationFlow(data,countries=[],extraRates={}){
 const root=document.querySelector('.rental-flow'),id=Number(new URLSearchParams(location.search).get('vehicle')),v=data.fleet.find(x=>x.id===id);
 if(!v){root.innerHTML='<div class="rental-empty"><h1>Find Your Ideal Ride</h1><p>Choose a vehicle from our fleet to start your reservation preview.</p><a class="btn blue" href="fleet.html">View full fleet</a></div>';return;}
 let saved={};try{saved=JSON.parse(sessionStorage.getItem('sxm-trip'))||{};}catch{}
 const money=n=>'$'+Number(n).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}),name=v.brand+' '+v.model.trim();let step=0,values={};
 const field=(label,key,type='text',required=false,extra='')=>`<label class="rental-field"><span>${label}${required?' <span aria-hidden="true">*</span>':''}</span><input name="${key}" type="${type}" ${required?'required':''} ${extra}></label>`;
 const loc=(label,key)=>`<label class="rental-field">${label}<select name="${key}" required>${data.bookingLocations.map(l=>`<option value="${esc(l.value)}">${esc(l.label)}</option>`).join('')}</select></label>`;
 const time=(label,key)=>`<label class="rental-field">${label}<select name="${key}" required>${Array.from({length:19},(_,i)=>{const h=8+Math.floor(i/2),t=String(h).padStart(2,'0')+':'+(i%2?'30':'00');return `<option value="${t}">${timeLabel(t)}</option>`;}).join('')}</select></label>`;
 const specs=[['Passengers',v.numberOfPassengers],['Luggage',v.amountOfLuggage],['Doors',v.numberOfDoors],['Transmission',v.transmission||'Not specified'],['Air conditioning',v.hasAirConditioning?'Included':'Not specified'],['Multimedia unit',v.hasMultiMediaUnit?'Included':'Not specified']];
 root.innerHTML=`<div class="rental-page-heading"><div><h1>Your Journey, Made Simple</h1><p>A few details now. A little more freedom ahead.</p></div></div><ol class="rental-steps" aria-label="Reservation progress">${['Vehicle','Reservation','Review'].map((t,i)=>`<li><button type="button" data-rental-step="${i}"><span>${i+1}</span>${t}</button></li>`).join('')}</ol><div class="rental-layout"><div class="rental-primary"><section data-rental-panel="0" class="rental-surface"><div class="rental-section-heading"><h2>Meet Your Ride</h2></div><div class="rental-vehicle-stage"><img src="${esc(v.cardImage||v.image)}" alt="${esc(name)}" width="600" height="350"></div><h3>${esc(name)}</h3><p>${esc(v.description)}</p><dl class="rental-spec-grid">${specs.map(([k,x])=>`<div><dt>${k}</dt><dd>${esc(x)}</dd></div>`).join('')}</dl><div class="rental-bottom-actions"><a href="fleet.html">Choose another car</a><button class="btn blue" type="button" data-rental-next>Continue</button></div></section><form data-rental-panel="1" class="rental-surface" hidden><div class="rental-section-heading"><h2>Make It Your Journey</h2><p>Fields marked * are required for this preview.</p></div><fieldset><legend>Pick-up & Return</legend><div class="rental-form-grid">${loc('Pick-up location','pickupLocation')}${loc('Return location','returnLocation')}${field('Pick-up date','pickupDate','date',true,`min="${rentalDate()}"`)}${field('Return date','returnDate','date',true,`min="${rentalDate()}"`)}${time('Pick-up time','pickupTime')}${time('Return time','returnTime')}</div><p class="rental-form-error" id="rental-date-error" role="alert"></p></fieldset><fieldset><legend>A Little Extra For Your Trip</legend><p>Choose extras to update your estimated trip total.</p><div class="rental-extras">${data.options.map((o,i)=>`<div class="rental-extra"><label>${o.usesAmount?`<select name="extra${i}" aria-label="${esc(o.name)} quantity">${Array.from({length:o.amountMax+1},(_,n)=>`<option value="${n}">${n}</option>`).join('')}</select>`:`<input type="checkbox" name="extra${i}" value="1">`}<span>${esc(o.name)}<small class="rental-extra-price">${Number.isFinite(extraRates[o.tsdCode])?money(extraRates[o.tsdCode])+'/day'+(o.usesAmount?' each':'')+(o.tsdCode==='CDW'?' · reference rate':''):'Price on request'}</small></span></label><details><summary>Details</summary><p>${esc(o.description)}</p></details></div>`).join('')}</div></fieldset><fieldset><legend>Contact Details</legend><div class="rental-form-grid">${field('First name','firstName','text',true,'minlength="2" autocomplete="given-name"')}${field('Last name','lastName','text',true,'minlength="2" autocomplete="family-name"')}${field('Email address','email','email',true,'autocomplete="email"')}${field('Confirm email address','emailVerify','email',true)}<div class="rental-field rental-country"><label for="rental-country-search">Country calling code *</label><div class="rental-country-control"><input id="rental-country-search" name="countrySearch" role="combobox" aria-expanded="false" aria-autocomplete="list" aria-controls="rental-country-list" autocomplete="off" placeholder="Search country or calling code" required><button type="button" id="rental-country-toggle" aria-label="Show country calling codes" aria-expanded="false" aria-controls="rental-country-list">⌄</button></div><input type="hidden" name="countryDialCode"><div id="rental-country-list" role="listbox" aria-label="Countries and calling codes" hidden></div></div>${field('Phone number','telephone','tel',true,'autocomplete="tel-national"')}${field('How did you hear about us? (Optional)','heardAbout')}</div></fieldset><details class="rental-driver-details"><summary>Address & Driver Details <span>Optional in this preview</span></summary><p>The company may require these details to complete your rental.</p><div class="rental-form-grid">${field('Street address','renterAddress1')}${field('Country','country')}${field('State / region','state')}${field('Postal code','zipCode')}${field('Driver’s license number','licenseNumber')}${field('License expiration date','licenseExpDate','date')}${field('Date of birth','dateOfBirth','date',false,`max="${rentalDate()}"`)}</div></details><fieldset><legend>Anything Else?</legend>${field('Coupon code (Optional)','coupon')}<small>Coupon validation will be available when live booking is connected.</small><label class="rental-field">Notes (Optional)<textarea name="notes" rows="3" maxlength="2000"></textarea></label></fieldset><div class="rental-bottom-actions"><button type="button" class="rental-back" data-rental-back>Back</button><button class="btn blue" type="submit">Review details</button></div></form><section data-rental-panel="2" class="rental-surface" hidden><div class="rental-section-heading"><h2>One Last Look</h2><p>Review your journey before finishing this demonstration.</p></div><div id="rental-review"></div><form id="rental-review-form"><p id="rental-policy-hint" class="rental-policy-hint">Check both policies to finish the preview.</p><div class="rental-policy"><label><input type="checkbox" required> <span>I have read the <a href="${BASE}assets/documents/Dollar_Thrifty_Terms_and_Conditions.pdf" target="_blank" rel="noopener">Terms and Conditions</a>.</span></label><label><input type="checkbox" required> <span>I have read the <a href="${BASE}assets/documents/Dollar_Thrifty_Rental_Policies.pdf" target="_blank" rel="noopener">Rental Policies</a>.</span></label></div><div class="rental-bottom-actions"><button type="button" class="rental-back" data-rental-back>Edit details</button><button class="btn blue" id="rental-finish" type="submit" disabled aria-describedby="rental-policy-hint">Finish preview</button></div></form></section><section data-rental-panel="3" class="rental-surface rental-finished" hidden><span class="rental-finish-icon" aria-hidden="true">✓</span><h2>Your Preview Is Complete</h2><p>You’ve reached the end of the redesigned booking experience. No reservation has been made and no confirmation email has been sent.</p><p>For a real reservation, continue to the company’s current booking website. You’ll need to enter your details there.</p><a class="btn blue" href="${BASE}">Open live booking</a><a href="fleet.html">Back to the fleet</a></section></div><aside class="rental-summary rental-surface" aria-label="Selected vehicle"><span class="rental-summary-label">Your selected ride</span><img src="${esc(v.cardImage||v.image)}" alt="" width="600" height="350"><span class="rental-category">${esc(v.type)}</span><h2>${esc(name)}</h2><p>${v.numberOfPassengers} passengers <span aria-hidden="true">·</span> ${esc(v.transmission||'Transmission not specified')}</p><div class="rental-published-rate">${v.publishedRate?`<div><strong>${money(v.publishedRate.day)}</strong><span>/ day</span></div><small>${money(v.publishedRate.week)} / week</small>`:'<strong>Rates on request</strong>'}</div><p class="rental-rate-note">Published reference rates. Estimated pricing is not a live quote. Final rates and availability are confirmed by the company.</p><div id="rental-cost-summary" aria-live="polite" aria-atomic="true"></div><div id="rental-trip-mini"></div><a class="rental-help" href="tel:+17215452393">Need a hand? +1 (721) 545-2393</a></aside></div>`;
 const form=root.querySelector('[data-rental-panel="1"]');
 for(const [key,val] of Object.entries({pickupDate:rentalDate(1),returnDate:rentalDate(4),pickupTime:'10:00',returnTime:'10:00',...saved})){const el=form.elements.namedItem(key);if(el&&typeof val==='string')el.value=val;}

 let selectedCountry=null,activeCountry=-1,matches=[];
 const countryInput=root.querySelector('#rental-country-search'),countryList=root.querySelector('#rental-country-list'),countryToggle=root.querySelector('#rental-country-toggle');
 function closeCountries(){countryList.hidden=true;countryInput.setAttribute('aria-expanded','false');countryToggle.setAttribute('aria-expanded','false');countryInput.removeAttribute('aria-activedescendant');activeCountry=-1;}
 function openCountries(all=false){const query=all?'':countryInput.value.trim().toLowerCase();matches=countries.filter(c=>(c.name+' '+c.code+' '+c.countryCode).toLowerCase().includes(query));activeCountry=-1;countryInput.removeAttribute('aria-activedescendant');countryList.innerHTML=matches.length?matches.map((c,i)=>`<button type="button" role="option" id="rental-country-${i}" data-country-index="${i}" tabindex="-1" aria-selected="${String(selectedCountry?.countryCode===c.countryCode)}"><span>${esc(c.name)}</span><strong>${esc(c.code)}</strong></button>`).join(''):'<p>No matching countries</p>';countryList.hidden=false;countryInput.setAttribute('aria-expanded','true');countryToggle.setAttribute('aria-expanded','true');}
 function selectCountry(i){const c=matches[i];if(!c)return;selectedCountry=c;countryInput.value=c.name+' ('+c.code+')';form.elements.countryDialCode.value=c.code;countryInput.setCustomValidity('');closeCountries();countryInput.focus();}
 countryInput.setCustomValidity('Choose a country from the list.');
 countryInput.addEventListener('focus',()=>openCountries(Boolean(selectedCountry)));
 countryInput.addEventListener('input',()=>{selectedCountry=null;form.elements.countryDialCode.value='';countryInput.setCustomValidity('Choose a country from the list.');openCountries();});
 countryToggle.addEventListener('click',()=>{if(countryList.hidden){countryInput.focus();openCountries(true);}else closeCountries();});
 countryList.addEventListener('click',e=>{const option=e.target.closest('[data-country-index]');if(option)selectCountry(Number(option.dataset.countryIndex));});
 countryInput.addEventListener('keydown',e=>{if(e.key==='Escape'){closeCountries();return;}if(e.key==='Tab'){closeCountries();return;}if(e.key==='Enter'&&!countryList.hidden){e.preventDefault();if(activeCountry>=0)selectCountry(activeCountry);return;}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(countryList.hidden)openCountries(Boolean(selectedCountry));activeCountry=Math.max(0,Math.min(matches.length-1,activeCountry+(e.key==='ArrowDown'?1:-1)));countryList.querySelectorAll('[role="option"]').forEach((el,i)=>{el.classList.toggle('is-highlighted',i===activeCountry);if(i===activeCountry){countryInput.setAttribute('aria-activedescendant',el.id);el.scrollIntoView({block:'nearest'});}});}});
 document.addEventListener('click',e=>{if(!e.target.closest('.rental-country'))closeCountries();});
 const reviewForm=root.querySelector('#rental-review-form');
 function updatePolicyButton(){const accepted=[...reviewForm.querySelectorAll('.rental-policy input')].every(c=>c.checked);root.querySelector('#rental-finish').disabled=!accepted;root.querySelector('#rental-policy-hint').hidden=accepted;}
 reviewForm.addEventListener('change',updatePolicyButton);updatePolicyButton();
 function updateCosts(){const current=Object.fromEntries(new FormData(form)),estimate=calculateRentalEstimate(v,data.options,extraRates,current),target=root.querySelector('#rental-cost-summary');if(!estimate){target.innerHTML='<p class="rental-cost-note">Choose valid dates to see your estimated total.</p>';return;}const line=(label,amount,detail='')=>`<div class="rental-cost-line"><span>${esc(label)}${detail?`<small>${esc(detail)}</small>`:''}</span><strong>${money(amount)}</strong></div>`;target.innerHTML=`<div class="rental-cost-heading">Trip estimate <span>${estimate.days} ${estimate.days===1?'day':'days'}</span></div>${line('Vehicle rental',estimate.vehicleTotal,estimate.weeks?estimate.weeks+' week(s)'+(estimate.dailyDays?' + '+estimate.dailyDays+' day(s)':''):estimate.days+' days')}${estimate.extras.map(x=>line(x.name+(x.quantity>1?' × '+x.quantity:''),x.total,money(x.rate)+'/day'+(x.quantity>1?' each':''))).join('')}${estimate.extras.length?'':'<p class="rental-cost-note">No extras selected</p>'}${line('Roadside service',estimate.roadside,money(2)+'/day')}${line('Airport / location fee',15)}${line('Subtotal',estimate.subtotal)}${line('Tax (5%)',estimate.tax)}${line('Surcharge (13%)',estimate.surcharge,'Applied after tax')}<div class="rental-cost-total"><span>Estimated total</span><strong>${money(estimate.total)}</strong></div>`;}
 form.addEventListener('input',e=>{if(['pickupDate','returnDate','pickupTime','returnTime'].includes(e.target.name)||e.target.name.startsWith('extra'))updateCosts();});form.addEventListener('change',updateCosts);updateCosts();
 const email=form.elements.emailVerify;email.addEventListener('input',()=>email.setCustomValidity(''));form.elements.email.addEventListener('input',()=>email.setCustomValidity(''));
 function show(n){step=n;root.querySelector('.rental-page-heading').hidden=n===3;root.querySelector('.rental-summary').hidden=n===3;root.classList.toggle('rental-complete',n===3);root.querySelectorAll('[data-rental-panel]').forEach(p=>p.hidden=Number(p.dataset.rentalPanel)!==n);root.querySelectorAll('[data-rental-step]').forEach((b,i)=>{b.disabled=i>step;b.closest('li').classList.toggle('is-current',i===Math.min(n,2));b.closest('li').classList.toggle('is-complete',i<n);if(i===Math.min(n,2))b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});if(n===2){renderReview();updatePolicyButton();}if(n===3){root.querySelector('.rental-steps').hidden=true;form.reset();values={};root.querySelector('#rental-review').innerHTML='';}if(n>0){const h=root.querySelector(`[data-rental-panel="${n}"] h2`);h.tabIndex=-1;h.focus({preventScroll:true});(n===3?h:root.querySelector('.rental-steps')).scrollIntoView({block:'start',behavior:'smooth'});}}
 function renderReview(){const extras=data.options.map((o,i)=>Number(values['extra'+i])?`${o.name}${o.usesAmount?' × '+values['extra'+i]:''}`:'').filter(Boolean);const row=(k,x)=>`<div><dt>${k}</dt><dd>${esc(x)}</dd></div>`;root.querySelector('#rental-review').innerHTML=`<div class="rental-review-block"><h3>Your Trip</h3><dl>${row('Vehicle',name)}${row('Pick-up',values.pickupLocation+' · '+values.pickupDate+' · '+timeLabel(values.pickupTime))}${row('Return',values.returnLocation+' · '+values.returnDate+' · '+timeLabel(values.returnTime))}</dl></div><div class="rental-review-block"><h3>Contact Details</h3><dl>${row('Name',values.firstName+' '+values.lastName)}${row('Email',values.email)}${row('Phone',values.countryDialCode+' '+values.telephone)}${row('Calling-code country',selectedCountry?.name||'')}${values.heardAbout?row('How you heard about us',values.heardAbout):''}</dl></div><div class="rental-review-block"><h3>Extras & Notes</h3><p>${esc(extras.join(', ')||'No extras selected')}</p>${values.notes?`<p>${esc(values.notes)}</p>`:''}${values.coupon?`<p>Coupon: ${esc(values.coupon)} (not validated)</p>`:''}</div>${['renterAddress1','country','state','zipCode','licenseNumber','licenseExpDate','dateOfBirth'].some(k=>values[k])?`<div class="rental-review-block"><h3>Address & Driver Details</h3><dl>${[['Address','renterAddress1'],['Country','country'],['State / region','state'],['Postal code','zipCode'],['License number','licenseNumber'],['License expiration','licenseExpDate'],['Date of birth','dateOfBirth']].filter(([,k])=>values[k]).map(([label,key])=>row(label,values[key])).join('')}</dl></div>`:''}`;root.querySelector('#rental-trip-mini').innerHTML=`<div class="rental-mini-trip"><strong>Your Trip</strong><p>Pick-up<br>${esc(values.pickupLocation)}<br>${esc(values.pickupDate)} · ${esc(timeLabel(values.pickupTime))}</p><p>Return<br>${esc(values.returnLocation)}<br>${esc(values.returnDate)} · ${esc(timeLabel(values.returnTime))}</p></div>`;}
 root.querySelector('[data-rental-next]').addEventListener('click',()=>show(1));root.querySelectorAll('[data-rental-back]').forEach(b=>b.addEventListener('click',()=>show(Math.max(0,step-1))));root.querySelectorAll('[data-rental-step]').forEach(b=>b.addEventListener('click',()=>show(Number(b.dataset.rentalStep))));
 form.addEventListener('submit',e=>{e.preventDefault();values=Object.fromEntries(new FormData(form));if(!selectedCountry){countryInput.setCustomValidity('Choose a country from the list.');countryInput.reportValidity();return;}if(values.email!==values.emailVerify){email.setCustomValidity('Please enter the same email address.');email.reportValidity();return;}if(!validateRentalDates(values)){root.querySelector('#rental-date-error').textContent='Choose a future pick-up date and return at least 24 hours after pick-up.';form.elements.returnDate.focus();return;}root.querySelector('#rental-date-error').textContent='';show(2);});
 root.querySelector('#rental-review-form').addEventListener('submit',e=>{e.preventDefault();if(!root.querySelector('#rental-finish').disabled)show(3);});show(0);
}
